var S=window.SugarCube, setup=S.setup, sv=S.State.variables;
function phoneBtnVisible(){ return jQuery('#phone-sidebar-btn').length > 0; }
try {
  var out = {};
  sv.flags = sv.flags || {}; sv.player = sv.player || {}; sv.player.core_traits = sv.player.core_traits || {};
  // 1. pre-acquisition: phone hidden
  sv.flags.phone_active = false; jQuery(document).trigger(':passagedisplay'); 
  // force a caption re-render
  setup.phone_purchase_flag; 
  out.purchaseFlag = setup.phone_purchase_flag;
  out.phoneEnabled = setup.phone_enabled;
  // 2. acquire phone
  window.applyFlagEffect('player', null, 'phone_active', 'set');
  out.phoneActiveSet = !!sv.flags.phone_active;
  // 3. Frank thread delivery on frank_caught
  window.applyFlagEffect('player', null, 'frank_caught', 'set');
  var convs = (setup.phone_data||{}).conversations||[];
  function trig(id){ var c=convs.filter(function(x){return x.id===id;})[0]; return c? setup.triggerConditionsSatisfied(c.trigger.conditions): null; }
  out.frank_after_catch_avail = trig('frank_after_catch');
  out.anon1_avail_corr0 = trig('anon_1');     // corruption 0 → false
  sv.player.core_traits.corruption = 45;
  out.anon1_avail_corr45 = trig('anon_1');     // → true
  // 4. photo gate logic via getCorruptionLevel-independent raw check is in render; check daily_topics corruption_min present
  var dts = (setup.phone_data||{}).daily_topics||[];
  function dt(id){ return dts.filter(function(x){return x.id===id;})[0]||{}; }
  out.lewd_min = dt('frank_photo_lewd').corruption_min;
  out.nude_min = dt('frank_photo_nude').corruption_min;
  out.selfie_min = dt('frank_photo_selfie').corruption_min || null;
  out.unknownName = (sv.npcs && sv.npcs['npc_unknown']) ? sv.npcs['npc_unknown'].name : 'MISSING';
  return JSON.stringify(out);
} catch(e){ return JSON.stringify({error:String(e)}); }

var sv=window.SugarCube.State.variables, setup=window.SugarCube.setup;
return JSON.stringify({
  npcKeys: Object.keys(sv.npcs||{}),
  resolveUnknown: setup.resolveNpcId ? setup.resolveNpcId('npc_unknown') : 'no-fn',
  threadNameForUnknown: (function(){ var id=setup.resolveNpcId('npc_unknown'); var d=(sv.npcs||{})[id]; return d?d.name:('npc_unknown'.replace('npc_','').replace(/_/g,' ')); })()
});
